byid={q[':question/math-academy-id']:q for q in qs}
cases=[];components=[]
for t,(level,src,p) in g.TEMPLATES.items():
 if not src:continue
 q=byid[src]; profiles=[]
 for i,f in enumerate(q[':question/answer-fields']):
  prof=('legacy_' if len(q[':question/answer-fields'])==2 and i==0 else 'observed_')+t
