(H/'original-widget-evidence.json').write_text(json.dumps({'path':str(ma),'sha256':hashlib.sha256(ma.read_bytes()).hexdigest(),'matching_widget':widgets,'q_161831_widget':'Not present among eight originally captured lesson question widgets; EDB worked solution/current field independently establish correction.'},indent=2,ensure_ascii=False)+'\n')
